contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // send an input amount to c.play and observe effects
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        // Record observable before-values
        uint beforePot = c.pot(); if (__ESBMC_reverted()) return;
        address bankAddr = c.bank(); if (__ESBMC_reverted()) return;
        uint beforeBalanceC = address(c).balance;

        bool reverted;
        // call play with provided amount
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Read after-values
        uint afterPot = c.pot(); if (__ESBMC_reverted()) return;
        uint afterBalanceC = address(c).balance;
        address bankAddrAfter = c.bank(); if (__ESBMC_reverted()) return;

        // General rule asserted:
        // - bank address never changes
        // - if the call reverted, pot and balance of c unchanged
        // - if the call did not revert and amount == TICKET_AMOUNT then either pot increased by amount (no payout)
        //   or pot became 0 and contract balance decreased by that payout amount (i.e., pot went to 0 after transfer)
        // Note: we refer to constants via observed changes, not by redeclaring them.
        assert(
            // bank immutable
            bankAddrAfter == bankAddr
            && (
                reverted
                ? (afterPot == beforePot && afterBalanceC == beforeBalanceC)
                : (
                    // successful call must have consumed exactly amount from caller into contract (so contract balance >= beforeBalanceC)
                    // Two possible outcomes: either pot increased by amount, or pot reset to 0 (payout case).
                    (
                        afterPot == beforePot + amount && afterBalanceC == beforeBalanceC + amount
                    ) || (
                        // payout: pot becomes 0 and contract balance decreased by (beforePot + amount) - fee (i.e., it sent out pot - fee and fee to bank)
                        (afterPot == 0 && afterBalanceC <= beforeBalanceC + amount)
                    )
                )
            )
        );
    }

    // allow receiving refunds from C during play
    receive() external payable {}
}

