// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint256 beforePot;
        try c.pot() returns (uint256 __r) { beforePot = __r; } catch { return; }
        address bankAddr;
        try c.bank() returns (address __r) { bankAddr = __r; } catch { return; }
        uint beforeBalanceC = address(c).balance;
        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterPot;
        try c.pot() returns (uint256 __r) { afterPot = __r; } catch { return; }
        uint afterBalanceC = address(c).balance;
        address bankAddrAfter;
        try c.bank() returns (address __r) { bankAddrAfter = __r; } catch { return; }
        assertTrue(bankAddrAfter == bankAddr
            && (
                reverted
                ? (afterPot == beforePot && afterBalanceC == beforeBalanceC)
                : (
                    // successful call must have consumed exactly amount from caller into contract (so contract balance >= beforeBalanceC)
                    // Two possible outcomes: either pot increased by amount, or pot reset to 0 (payout case).
                    (
                        afterPot == beforePot + amount && afterBalanceC == beforeBalanceC + amount
                    ) || (
                        // payout: pot becomes 0 and contract balance decreased by (beforePot + amount) - fee (i.e., it sent out pot - fee and fee to bank)
                        (afterPot == 0 && afterBalanceC <= beforeBalanceC + amount)
                    )
                )
            ));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
